	public void TrfrConn()
	{
		//IL_0002: Unknown result type (might be due to invalid IL or missing references)
		//IL_000c: Expected O, but got Unknown
		CnTrAcc = new OleDbConnection();
		OleDbConnection cnTrAcc = CnTrAcc;
		cnTrAcc.ConnectionString = ("Provider=Microsoft.Jet.OLEDB.4.0;Data Source=" + TrfrMdbName) ?? "";
		cnTrAcc.Open();
		cnTrAcc = null;
	}

	public void OpenRecordsetTrfrAcc(string QRY)
	{
		cmdAcc.Connection = CnTrAcc;
		cmdAcc.CommandText = QRY;
		Imp = cmdAcc.ExecuteReader();
	}

