	private void WH_AcOpbl()
	{
		DC_Main.ExeQuteDc("DELETE FROM OP_DATA WHERE CO_CODE = '" + DC_Main.MCo_code + "'");
		DC_Main.RsQry = "Select A.AC_CODE,B.AC_NAME,B.AC_ADD1,B.AC_MOBILE,format(Sum(A.CR_AMT-A.DR_AMT),'0.00') as Amount,format(SUM(iif(A.IT_TYPE = 'G',iif(A.SIGN = '+',A.FINE_WT,-A.FINE_WT),0)),'0.000') as GoldWt,format(sum(iif(A.IT_TYPE = 'S',iif(A.SIGN = '+',A.FINE_WT,-A.FINE_WT),0)),'0.000') as SilverWt  FROM AC_DATA AS A LEFT JOIN AC_MAST AS B ON A.CO_CODE = B.CO_CODE AND A.AC_CODE = B.AC_CODE WHERE A.CO_CODE = '" + DC_Main.MCo_code + "' and VCH_DATE <= #" + Strings.Format((object)DC_Main.MCl_dt, "MM/dd/yyyy") + "#   GROUP BY A.AC_CODE,B.AC_NAME,B.AC_ADD1,B.AC_MOBILE  HAVING (Sum(A.CR_AMT-A.DR_AMT)+ SUM(iif(A.IT_TYPE = 'G',iif(A.SIGN = '+',A.FINE_WT,-A.FINE_WT),0))+sum(iif(A.IT_TYPE = 'S',iif(A.SIGN = '+',A.FINE_WT,-A.FINE_WT),0))) <> 0 ORDER BY B.AC_NAME ";
		OpenRecordsetTrfrAcc(DC_Main.RsQry);
		DC_Main.Rshlp.Clear();
		DC_Main.Rshlp.Columns.Clear();
		DC_Main.Rshlp.Load((IDataReader)Imp);
		Imp.Close();
		ProgressBar1.Value = 0;
		ProgressBar1.Maximum = DC_Main.Rshlp.Rows.Count;
		lblBook.Text = "Party Opning";
		Application.DoEvents();
		DC_Main.M = 0;
		checked
		{
			while (DC_Main.M < DC_Main.Rshlp.Rows.Count)
