			DC_Main.ExeQuteDc("UPDATE LOCT_MAST SET TRY_DATE = '" + Strings.Format((object)DateAndTime.Now.AddDays(10.0), "MM/dd/yyyy") + "' WHERE CO_CODE  = '01' AND LC_CODE = '00'");
			DC_Main.ExeQuteMc("UPDATE YEAR_MAST SET OP_DATE = '" + Strings.Format((object)DateAndTime.Now, "MM/dd/yyyy") + "' WHERE CO_CODE  = '" + DC_Main.MCo_code + "' ");
			DC_Main.ExeQuteDc("UPDATE YEAR_MAST SET OP_DATE = '" + Strings.Format((object)DateAndTime.Now, "MM/dd/yyyy") + "' WHERE CO_CODE  = '" + DC_Main.MCo_code + "' ");
		}
		Interaction.MsgBox((object)"Process Are Complete....", (MsgBoxStyle)64, (object)null);
		Application.Exit();
	}

