	private void WhSales_Reset()
	{
		if (Operators.CompareString(DC_Main.MCo_Type, "", false) == 0)
		{
			DC_Main.RsQry = "SELECT A.* FROM RATE_CUT_DATA AS A INNER JOIN BOOK_DATA AS B ON A.CO_CODE = B.CO_CODE AND A.CO_BOOK = B.CO_BOOK WHERE A.CO_CODE = '" + DC_Main.MCo_code + "' AND A.LC_CODE = '" + DC_Main.MLc_code + "' AND B.MAIN_BOOK = 'WH SALES' AND B.RESET_BOOK = 'Y'  AND A.TOT_FINE_DR = A.TOT_FINE_DR  AND A.SL_BILL_OS = 0 AND A.PR_BILL_OS = 0 AND A.VCH_DATE <= '" + Strings.Format((object)Conversions.ToDate(mClDate.Text), "MM/dd/yyyy") + "' ORDER BY CO_BOOK,VCH_DATE,VCH_NO";
