		{
			DC_Main.RsQry = "SELECT A.* FROM RATE_CUT_DATA AS A INNER JOIN BOOK_DATA AS B ON A.CO_CODE = B.CO_CODE AND A.CO_BOOK = B.CO_BOOK WHERE A.CO_CODE = '" + DC_Main.MCo_code + "' AND A.LC_CODE = '" + DC_Main.MLc_code + "' AND DATA_TRFR = 'Y' AND B.MAIN_BOOK = WH SALES' AND B.RESET_BOOK = 'Y'  ORDER BY CO_BOOK,VCH_DATE,VCH_NO";
		}
