		lblBook.Text = "Retail Dhiran Account Update";
		((Control)ProgressBar1).Visible = true;
		if ((int)Interaction.MsgBox((object)"Are You Sure To Import Old Software Dharan Account Update iN Next Software ?", (MsgBoxStyle)4, (object)DC_Main.MsgTitle) == 6)
		{
			((FileDialog)DlgOpn).Filter = "MDB (*.mdb)|*.mdb";
			((FileDialog)DlgOpn).Title = "Open File";
			if ((int)((CommonDialog)DlgOpn).ShowDialog() != 1)
