	private void WhSql_BarData()
	{
		DC_Main.ExeQuteDc("DELETE FROM BAR_DATA WHERE CO_CODE = '" + DC_Main.MCo_code + "' AND LC_CODE = '" + DC_Main.MLc_code + "' ");
		DC_Main.ExeQuteDc("DELETE FROM BAR_DETL WHERE CO_CODE = '" + DC_Main.MCo_code + "' AND LC_CODE = '" + DC_Main.MLc_code + "' ");
		DC_Main.ExeQuteDc("DELETE FROM BAR_IDTL WHERE CO_CODE = '" + DC_Main.MCo_code + "' AND LC_CODE = '" + DC_Main.MLc_code + "' ");
		string text = "00001";
		DC_Main.RsQry = "SELECT B.IT_TYPE,A.IT_CODE FROM MAIN_TAG_DATA AS A LEFT JOIN ITEM_MAST AS B ON A.CO_CODE = B.CO_CODE AND A.IT_CODE = B.IT_CODE  WHERE A.CO_CODE = '" + DC_Main.MCo_code + "' AND TAG_NO <> '' GROUP BY B.IT_TYPE,A.IT_CODE ORDER BY B.IT_TYPE,A.IT_CODE ";
		DataTable dataTable = OpenRecordsetTrfr(DC_Main.RsQry);
		ProgressBar1.Value = 0;
		ProgressBar1.Maximum = dataTable.Rows.Count;
		lblBook.Text = "Tag Transfer";
		Application.DoEvents();
		DC_Main.M = 0;
		checked
		{
			while (DC_Main.M < dataTable.Rows.Count)
			{
				DC_Main.RsQry = Conversions.ToString(Operators.ConcatenateObject(Operators.ConcatenateObject((object)("SELECT * FROM BAR_DETL WHERE CO_CODE = '" + DC_Main.MCo_code + "' AND IT_CODE = '"), dataTable.Rows[DC_Main.M]["IT_CODE"]), (object)"'"));
				DataTable table = OpenRecordsetTrfr(DC_Main.RsQry);
				DataView dataView = new DataView(table);
				DC_Main.RsQry = Conversions.ToString(Operators.ConcatenateObject(Operators.ConcatenateObject((object)("SELECT A.TAG_NO,A.IT_CODE,C.VCH_SRNO  from (MAIN_TAG_DATA AS A INNER JOIN BAR_DETL AS C ON A.CO_CODE = C.CO_CODE  And A.TAG_NO = C.TAG_NO And A.VCH_SRNO = C.VCH_SRNO And A.IT_CODE = C.IT_CODE)LEFT JOIN ITEM_MAST AS B ON A.CO_CODE = B.CO_CODE And A.IT_CODE = B.IT_CODE  WHERE A.CO_CODE = '" + DC_Main.MCo_code + "'  AND A.CO_YEAR = '" + DC_Main.MCo_year + "' AND C.IT_CODE = '"), dataTable.Rows[DC_Main.M]["IT_CODE"]), (object)"' And A.TAG_NO <> '' "));
				DC_Main.RsQry += " GROUP BY A.TAG_NO,A.IT_CODE,C.VCH_SRNO ";
				DC_Main.RsQry += " HAVING SUM(CASE WHEN SIGN='+' THEN A.VCH_SRNO ELSE -A.VCH_SRNO END) > 0  ORDER BY A.TAG_NO";
				DC_Main.Rshlp = OpenRecordsetTrfr(DC_Main.RsQry);
				DC_Main.i = 0;
				int num = 0;
				while (DC_Main.i < DC_Main.Rshlp.Rows.Count)
