	private void btnAcMastReImport_Click(object sender, EventArgs e)
	{
		//IL_002a: Unknown result type (might be due to invalid IL or missing references)
		//IL_0030: Invalid comparison between Unknown and I4
		//IL_0099: Unknown result type (might be due to invalid IL or missing references)
		//IL_005e: Unknown result type (might be due to invalid IL or missing references)
		//IL_0064: Invalid comparison between Unknown and I4
		lblBook.Text = "Ac Master ReImport..";
		((Control)ProgressBar1).Visible = true;
		if ((int)Interaction.MsgBox((object)"Are You Sure To ReImport Ac Master Access to Next Software.... ?", (MsgBoxStyle)4, (object)DC_Main.MsgTitle) == 6)
		{
			((FileDialog)DlgOpn).Filter = "MDB (*.mdb)|*.mdb";
			((FileDialog)DlgOpn).Title = "Open File";
			if ((int)((CommonDialog)DlgOpn).ShowDialog() != 1)
			{
				return;
			}
			TrfrMdbName = ((FileDialog)DlgOpn).FileName;
			TrfrConn();
			Access_To_Next_Ac_Update();
		}
		Interaction.MsgBox((object)"Process Are Complete....", (MsgBoxStyle)64, (object)null);
		Application.Exit();
	}

	private void Access_To_Next_Ac_Update()
	{
		DC_Main.RsQry = "SELECT * FROM AC_MAST WHERE CO_CODE = '" + DC_Main.MCo_code + "' ORDER BY AC_CODE ";
