		lblBook.Text = "Ac Master ReImport..";
		((Control)ProgressBar1).Visible = true;
		if ((int)Interaction.MsgBox((object)"Are You Sure To All Item Last Tag no Insert in SRNO_MAST To Next Software.... ?", (MsgBoxStyle)4, (object)DC_Main.MsgTitle) == 6)
		{
			((FileDialog)DlgOpn).Filter = "MDB (*.mdb)|*.mdb";
			((FileDialog)DlgOpn).Title = "Open File";
			if ((int)((CommonDialog)DlgOpn).ShowDialog() != 1)
			{
				return;
			}
			TrfrMdbName = ((FileDialog)DlgOpn).FileName;
			TrfrConn();
			Tag_SrNo_Mast();
		}
		Interaction.MsgBox((object)"Process Are Complete....", (MsgBoxStyle)64, (object)null);
		Application.Exit();
	}

	private void Tag_SrNo_Mast()
	{
		DC_Main.RsQry = "SELECT B.IT_TYPE,A.IT_CODE FROM MAIN_STOCK AS A LEFT JOIN ITEM_MAST AS B ON A.CO_CODE = B.CO_CODE AND A.IT_CODE = B.IT_CODE  WHERE A.CO_CODE = '" + DC_Main.MCo_code + "' AND TAG_NO <> '' GROUP BY B.IT_TYPE,A.IT_CODE ORDER BY B.IT_TYPE,A.IT_CODE ";
		OpenRecordsetTrfrAcc(DC_Main.RsQry);
		DC_Main.Rshlp.Clear();
		DC_Main.Rshlp.Columns.Clear();
		DC_Main.Rshlp.Load((IDataReader)Imp);
		Imp.Close();
		ProgressBar1.Value = 0;
		ProgressBar1.Maximum = DC_Main.Rshlp.Rows.Count;
		lblBook.Text = "Party Touch";
		Application.DoEvents();
		DC_Main.M = 0;
		checked
		{
			while (DC_Main.M < DC_Main.Rshlp.Rows.Count)
			{
				DataTable rshlp = DC_Main.Rshlp;
				DC_Main.RsQry = Conversions.ToString(Operators.ConcatenateObject(Operators.ConcatenateObject((object)("SELECT TOP 1 * FROM BAR_DETL WHERE CO_CODE = '" + DC_Main.MCo_code + "' AND IT_CODE = '"), DC_Main.Rshlp.Rows[DC_Main.M]["IT_CODE"]), (object)"' ORDER BY TAG_NO DESC"));
				OpenRecordsetTrfrAcc(DC_Main.RsQry);
				if (Imp.Read())
				{
					DC_Main.ExeQuteDc(("DELETE FROM SRNO_MAST WHERE CO_CODE = '" + DC_Main.MCo_code + "' AND LC_CODE = '" + DC_Main.MLc_code + "' AND TAG_SRNO = " + Conversions.ToString(DC_Main.M + 100000)) ?? "");
					DC_Main.RsQry = Conversions.ToString(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject((object)("INSERT INTO SRNO_MAST(CO_CODE,LC_CODE,TAG_SRNO,VCH_SRNO,TAG_NO,IT_CODE) VALUES  ('" + DC_Main.MCo_code + "','" + DC_Main.MLc_code + "'," + Conversions.ToString(DC_Main.M + 100000) + ","), Imp["VCH_SRNO"]), (object)",'"), Imp["TAG_NO"]), (object)"','"), Imp["IT_CODE"]), (object)"')"));
					DC_Main.OpenRecordSetDc(DC_Main.RsQry);
				}
				Imp.Close();
				rshlp = null;
				DC_Main.M++;
				ProgressBar progressBar;
				(progressBar = ProgressBar1).Value = progressBar.Value + 1;
				Application.DoEvents();
			}
		}
	}

