	private void Plus_OpBl()
	{
		//IL_0045: Unknown result type (might be due to invalid IL or missing references)
		//IL_004b: Invalid comparison between Unknown and I4
		DC_Main.ExeQuteDc("DELETE FROM OP_DATA WHERE CO_CODE = '" + DC_Main.MCo_code + "' AND LC_CODE = '" + DC_Main.MLc_code + "' ");
		if ((int)Interaction.MsgBox((object)"A and B Data Mearge Then Importy", (MsgBoxStyle)4, (object)DC_Main.MsgTitle) == 6)
		{
			DC_Main.RsQry = "Select A.AC_CODE,B.AC_NAME,B.AC_ADD1,B.AC_MOBILE,'A' As DATA_TYPE,Sum(A.CR_AMT-A.DR_AMT) as Amount,SUM(CASE WHEN A.IT_TYPE = 'G' THEN (CASE WHEN A.SIGN = '+' THEN A.FINE_WT ELSE -A.FINE_WT END )ELSE 0 END) as GoldWt,sum(CASE WHEN A.IT_TYPE = 'S' THEN (CASE WHEN A.SIGN = '+' THEN A.FINE_WT ELSE -A.FINE_WT END) ELSE 0 END) as SilverWt,sum(CASE WHEN A.IT_TYPE = 'D' THEN (CASE WHEN A.SIGN = '+' THEN A.FINE_WT ELSE -A.FINE_WT END) ELSE 0 END) as DmWt,sum(CASE WHEN A.SIGN = '+' THEN A.DM_PCS ELSE -A.DM_PCS END) As DmPcs   FROM AC_DATA AS A INNER JOIN AC_MAST AS B ON A.CO_CODE = B.CO_CODE AND A.AC_CODE = B.AC_CODE WHERE A.CO_CODE = '" + DC_Main.MCo_code + "' and VCH_DATE <= '" + Strings.Format((object)DC_Main.MCl_dt, "MM/dd/yyyy") + "'   GROUP BY A.AC_CODE,B.AC_NAME,B.AC_ADD1,B.AC_MOBILE  HAVING Sum(A.CR_AMT-A.DR_AMT)+ SUM(CASE WHEN A.IT_TYPE = 'G' THEN (CASE WHEN A.SIGN = '+' THEN A.FINE_WT ELSE -A.FINE_WT END )ELSE 0 END) + sum(CASE WHEN A.IT_TYPE = 'S' THEN (CASE WHEN A.SIGN = '+' THEN A.FINE_WT ELSE -A.FINE_WT END) ELSE 0 END)  <> 0 ORDER BY B.AC_NAME ";
		}
		else
		{
			DC_Main.RsQry = "Select A.AC_CODE,B.AC_NAME,B.AC_ADD1,B.AC_MOBILE,A.DATA_TYPE,Sum(A.CR_AMT-A.DR_AMT) as Amount,SUM(CASE WHEN A.IT_TYPE = 'G' THEN (CASE WHEN A.SIGN = '+' THEN A.FINE_WT ELSE -A.FINE_WT END )ELSE 0 END) as GoldWt,sum(CASE WHEN A.IT_TYPE = 'S' THEN (CASE WHEN A.SIGN = '+' THEN A.FINE_WT ELSE -A.FINE_WT END) ELSE 0 END) as SilverWt,sum(CASE WHEN A.IT_TYPE = 'D' THEN (CASE WHEN A.SIGN = '+' THEN A.FINE_WT ELSE -A.FINE_WT END) ELSE 0 END) as DmWt,sum(CASE WHEN A.SIGN = '+' THEN A.DM_PCS ELSE -A.DM_PCS END) As DmPcs   FROM AC_DATA AS A INNER JOIN AC_MAST AS B ON A.CO_CODE = B.CO_CODE AND A.AC_CODE = B.AC_CODE WHERE A.CO_CODE = '" + DC_Main.MCo_code + "' and VCH_DATE <= '" + Strings.Format((object)DC_Main.MCl_dt, "MM/dd/yyyy") + "'   GROUP BY A.AC_CODE,B.AC_NAME,B.AC_ADD1,B.AC_MOBILE,A.DATA_TYPE  HAVING Sum(A.CR_AMT-A.DR_AMT)+ SUM(CASE WHEN A.IT_TYPE = 'G' THEN (CASE WHEN A.SIGN = '+' THEN A.FINE_WT ELSE -A.FINE_WT END )ELSE 0 END) + sum(CASE WHEN A.IT_TYPE = 'S' THEN (CASE WHEN A.SIGN = '+' THEN A.FINE_WT ELSE -A.FINE_WT END) ELSE 0 END)  <> 0 ORDER BY B.AC_NAME,A.DATA_TYPE ";
		}
		DC_Main.Rshlp = OpenRecordsetTrfr(DC_Main.RsQry);
		ProgressBar1.Value = 0;
		ProgressBar1.Maximum = DC_Main.Rshlp.Rows.Count;
		lblBook.Text = "Party Opning";
		Application.DoEvents();
		DC_Main.M = 0;
		checked
		{
			while (DC_Main.M < DC_Main.Rshlp.Rows.Count)
			{
				DataTable rshlp = DC_Main.Rshlp;
				if (Math.Abs(Conversion.Val(RuntimeHelpers.GetObjectValue(rshlp.Rows[DC_Main.M]["Amount"]))) + Math.Abs(Conversion.Val(RuntimeHelpers.GetObjectValue(rshlp.Rows[DC_Main.M]["GoldWt"]))) + Math.Abs(Conversion.Val(RuntimeHelpers.GetObjectValue(rshlp.Rows[DC_Main.M]["SilverWt"]))) != 0.0)
				{
					DC_Main.RsQry = Conversions.ToString(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject(Operators.ConcatenateObject((object)("INSERT INTO OP_DATA(CO_CODE,LC_CODE,CO_YEAR,CO_BOOK,VCH_NO,AC_CODE,  OP_AMT,OP_SIGN,FINE_BAL,FINE_SIGN,SL_FINE_BAL,SL_FINE_SIGN,  DATA_TYPE,MAIN_USER,ADD_USER,ADD_DATE) VALUES  ('" + DC_Main.MCo_code + "','" + DC_Main.MLc_code + "','" + DC_Main.MCo_year + "','000','00000','"), rshlp.Rows[DC_Main.M]["AC_CODE"]), (object)"', "), (object)" "), (object)Math.Abs(Conversion.Val(RuntimeHelpers.GetObjectValue(rshlp.Rows[DC_Main.M]["Amount"])))), (object)","), Interaction.IIf(Operators.ConditionalCompareObjectGreater(rshlp.Rows[DC_Main.M]["Amount"], (object)0, false), (object)"'C'", (object)"'D'")), (object)","), (object)Math.Abs(Conversion.Val(RuntimeHelpers.GetObjectValue(rshlp.Rows[DC_Main.M]["GoldWt"])))), (object)","), Interaction.IIf(Operators.ConditionalCompareObjectGreater(rshlp.Rows[DC_Main.M]["GoldWt"], (object)0, false), (object)"'C'", (object)"'D'")), (object)","), (object)Math.Abs(Conversion.Val(RuntimeHelpers.GetObjectValue(rshlp.Rows[DC_Main.M]["SilverWt"])))), (object)","), Interaction.IIf(Operators.ConditionalCompareObjectGreater(rshlp.Rows[DC_Main.M]["SilverWt"], (object)0, false), (object)"'C'", (object)"'D'")), (object)", "), (object)" '"), rshlp.Rows[DC_Main.M]["DATA_TYPE"]), (object)"','"), (object)DC_Main.MCo_User), (object)"','',NULL)"));
					DC_Main.ExeQuteDc(DC_Main.RsQry);
				}
				rshlp = null;
